/*
 * A040814  Continued fraction for sqrt(844).
 * https://oeis.org/A040814
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, cofr, easy
 * Formula:   a(0) = floor(sqrt(844)); for n>0, a(n) is the (n‑th) term in the
 *            continued‑fraction expansion of sqrt(844). The continued
 *            fraction of sqrt(D) is periodic; the first term a(0) is obtained
 *            by floor_sqrt(D), and the subsequent terms are generated by the
 *            classical recurrence (m_k, d_k, a_k). The sequ...
 * Range:     u8 none, u16 n <= 88, u32 n <= 88, u64 n <= 88, u128 n <= 88,
 *            big any n
 * Helpers:   floor_sqrt
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include "../utils/floor_sqrt.h"

seq_t a(idx_t n)
{
    /* 844 is fixed for this sequence */
    static const seq_t S = (seq_t)844;

    /* static state persistent across calls */
    static seq_t a0 = 0;          /* floor(sqrt(S))   */
    static seq_t *period = NULL; /* array of periodic terms a(1), a(2), ... */
    static size_t period_len = 0;
    static size_t period_cap = 0;
    static int initialized = 0;

    /* initialise once  */
    if (!initialized) {
        /* first term */
        a0 = floor_sqrt(S);

        /* build the periodic part */
        size_t cap = 16;
        period = (seq_t *)malloc(cap * sizeof(seq_t));
        if (!period) exit(EXIT_FAILURE);
        period_cap = cap;

        seq_t m = 0;
        seq_t d = 1;
        seq_t a = a0;
        while (1) {
            /* next values using 64‑bit intermediates to avoid overflow */
            idx_t mt = (idx_t)d * (idx_t)a - (idx_t)m;
            idx_t dt = ((idx_t)S - mt * mt) / (idx_t)d;
            idx_t at = ((idx_t)a0 + mt) / dt;

            /* store the periodic term a_{k+1} */
            if (period_len == period_cap) {
                period_cap *= 2;
                seq_t *tmp = (seq_t *)realloc(period, period_cap * sizeof(seq_t));
                if (!tmp) {
                    free(period);
                    exit(EXIT_FAILURE);
                }
                period = tmp;
            }
            period[period_len++] = (seq_t)at;

            m = (seq_t)mt;
            d = (seq_t)dt;
            a = (seq_t)at;

            /* end of period when d == 1 (next term would be 2*a0) */
            if (d == (seq_t)1) break;
        }
        initialized = 1;
    }

    /* answer the query */
    if (n == (idx_t)0) return a0;
    /* periodic part starts at index 1 */
    idx_t idx = (n - 1) % period_len;
    return period[idx];
}
